1	/**
2	 * A generic class that represents a season
3	 * of the year
4	 *
5	 * @version 2022.02.16
6	 */
7	public class Season
8	{
9	    private final String name;
10	    private int aveTemperature;
11	    private final int tempChange;
12	    // current temperature drifts around aveTemperature each step within ±tempChange
13	    private int currentTemp;
14	
15	    /**
16	     * Initialise the Season object
17	     *
18	     * @param name (String) the name of the season
19	     * @param aveTemperature (int) the average temperature of this season
20	     * @param tempChange (int) the amount that the season's temperature can go up or down from the average temperature
21	     */
22	    public Season(String name, int aveTemperature, int tempChange)
23	    {
24	        this.name = name;
25	        this.aveTemperature = aveTemperature;
26	        this.tempChange = tempChange;
27	        this.currentTemp = aveTemperature;
28	    }
29	
30	    /**
31	     * @return (String) the name of the season
32	     */
33	    public String getName()
34	    {
35	        return name;
36	    }
37	
38	    /**
39	     * @return (int) average Temperature
40	     */
41	    public int getAveTemperature()
42	    {
43	        return aveTemperature;
44	    }
45	
46	    /**
47	     * Increment the season's average temperature by the given parameter
48	     *
49	     * @param inc (int) the increment
50	     */
51	    public void incAveTemperature(int inc)
52	    {
53	        aveTemperature += inc;
54	    }
55	
56	    /**
57	     * @return (int) The temperature change.
58	     */
59	    public int getTempChange()
60	    {
61	        return tempChange;
62	    }
63	
64	    /**
65	     * @return (int) The upper limit temperature that the season could reach
66	     */
67	    public int getUpperLimitTemp()
68	    {
69	        return aveTemperature + tempChange;
70	    }
71	
72	    /**
73	     * @return (int) The lower limit temperature that the season could drop to
74	     */
75	    public int getLowerLimitTemp()
76	    {
77	        return aveTemperature - tempChange;
78	    }
79	
80	    /**
81	     * @return (int) The current temperature for this season
82	     */
83	    public int getCurrentTemperature()
84	    {
85	        return currentTemp;
86	    }
87	
88	    /**
89	     * Shift the current temperature by the given amount.
90	     *
91	     * @param inc (int) degrees to add (negative to decrease)
92	     */
93	    public void incrementCurrentTemperature(int inc)
94	    {
95	        currentTemp += inc;
96	    }
97	}
