137	    /**
138	     * Populate the simulation with the chosen animals.
139	     * First reading the data relating to each animal,
140	     * then creating and adding to the list of species the right number of each animal.
141	     *
142	     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
143	     * @param field (Field) The field in which the animals will evolve.
144	     */
145	    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
146	    {
147	        idxOfColorToUseNext = 0;
148	        Location freeLocationToPlaceAnimal;
149	
150	        for(String animalName : animalsToCreate.keySet()) {
151	            animalReader.extractDataFor(animalName);
152	            if (animalsToCreate.get(animalName) != 0)
153	            {
154	                // Retrieve appropriate data.
155	                String name = animalReader.getName();
156	                int maximumTemperature = animalReader.getMaximumTemperature();
157	                int minimumTemperature = animalReader.getMinimumTemperature();
158	                int maxAge = animalReader.getMaximumAge();
159	                int breedingAge = animalReader.getBreedingAge();
160	                double breedingProbability = animalReader.getBreedingProbability();
161	                int maxLitterSize = animalReader.getMaxLitterSize();
162	                int nutritionalValue = animalReader.getNutritionalValue();
163	                boolean hibernates = animalReader.canHibernate();
164	                boolean isNocturnal = animalReader.isNocturnal();
165	
166	                if (animalReader.isPredator()) {
167	                    // Predator object should be created, retrieving appropriate data.
168	                    int strength = animalReader.getStrength();
169	
170	                    // Creating the right number of Predator objects.
171	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
172	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
173	                        Predator newPredator = new Predator(strength, field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
174	                        speciesToEvolveInSimulation.add(newPredator);
175	                    }
176	                }
177	                else {
178	                    // Animal object should be created
179	                    // Creating the right number of Animal objects.
180	                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
181	                        freeLocationToPlaceAnimal = findAvailableLocation(field);
182	                        Animal newAnimal = new Animal(field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
183	                        speciesToEvolveInSimulation.add(newAnimal);
184	                    }
185	                }
186	
187	                // Setting the color for this species.
188	                view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
189	                idxOfColorToUseNext ++;
190	            }
191	        }
192	    }
