194	    /**
195	     * Find an available location for an object to be created in the simulation field.
196	     * The simulation is chosen at random and is changed if the randomly selected cell
197	     * already contains an object.
198	     *
199	     * @param field (Field) The simulation's field.
200	     * @return (Location) the available location found.
201	     */
202	    private Location findAvailableLocation(Field field)
203	    {
204	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
205	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
206	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
207	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
208	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
209	        }
210	        return new Location(randomDepth, randomWidth);
211	    }
