139	            currentHealth = maxHealth;
140	        }
141	    }
142	
143	    /**
144	     * Increase the plant's health by one if the random number meets the growing probability
145	     */
146	    private void grow()
147	    {
148	        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
