64	
65	        JLabel welcomeLabel = createWelcomeLabel("Welcome to the Ultimate Simulator 3000");
66	        // HABITAT CHOICE SECTION
67	        JComboBox habitatListDisplay = createListDisplayFromList(habitatList);
68	        Box habitatChoiceComponent = createHabitatChoiceComponent(habitatListDisplay);
69	        // CLIMATE CHANGE SCENARIO CHANGE SECTION
70	        JComboBox scenarioListDisplay = createListDisplayFromList(climateChangeScenarioList);
71	        Box scenarioChoiceComponent = createScenarioChoiceComponent(scenarioListDisplay);
72	        // ANIMAL CHOICE SECTION
73	        JPanel animalChoiceComponent = createAnimalChoiceComponent();
74	
75	        // SIMULATE BUTTON
76	        JButton actionButton = new JButton("Simulate");
77	        ActionListener launchSim = e -> {
78	            getInputsAndLaunchSimulation(habitatListDisplay, animalNumberReceivers, scenarioListDisplay);
79	        };
80	        actionButton.addActionListener(launchSim);
81	
82	        // PUTTING THE UI TOGETHER
83	        Box choiceComponents = Box.createVerticalBox();
84	        choiceComponents.setBorder(BorderFactory.createEmptyBorder(30,0,10,0));
