160	    /**
161	     * Create the component to guide users through their choice of animals and allow them to make such choice.
162	     * @return (JPanel) The created UI component.
163	     */
164	    private JPanel createAnimalChoiceComponent()
165	    {
166	        JPanel animalChoiceComponent = new JPanel();
167	        animalChoiceComponent.setLayout(new BorderLayout());
168	
169	        // Labels to guide animals choice.
170	        JLabel animalChoicePrompt = new JLabel("Please choose the animals you want to see evolve in this habitat:");
171	        JLabel animalChoiceExplanationPrompt = new JLabel("(Input the number of each of these animals you want to include, we recommend adding twice the number of preys than predators)");
172	        animalChoicePrompt.setAlignmentX(JLabel.CENTER_ALIGNMENT);
173	        animalChoiceExplanationPrompt.setAlignmentX(JLabel.CENTER_ALIGNMENT);
